-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.release_marks (
  fingerprint text not null,
  mark text not null,
  checked_by text not null,
  checked_at timestamp with time zone default now() not null,
  constraint release_marks_pkey PRIMARY KEY (fingerprint, mark),
  constraint release_marks_checked_by_check CHECK (((length(btrim(checked_by)) >= 1) AND (length(btrim(checked_by)) <= 320))),
  constraint release_marks_fingerprint_check CHECK ((fingerprint ~ '^[0-9a-f]{32}$'::text)),
  constraint release_marks_mark_check CHECK ((mark = ANY (ARRAY['phone'::text, 'answers'::text, 'announcement'::text])))
);

alter table public.release_marks enable row level security;
